import { createHmac, timingSafeEqual } from "node:crypto";

export interface Claims { agent: string; jira: string; run: string; exp: number }
const sign = (body: string, key: string) => createHmac("sha256", key).update(body).digest("base64url");

export const signToken = (claims: Claims, key: string): string => {
  const body = Buffer.from(JSON.stringify(claims)).toString("base64url");
  return `${body}.${sign(body, key)}`; // anyone can read the claims; only the key holder can sign them
};

export const verifyToken = (token: string, key: string, now = Date.now()): Claims | null => {
  const [body = "", mac = ""] = token.split(".");
  const want = Buffer.from(sign(body, key)), got = Buffer.from(mac);
  if (got.length !== want.length || !timingSafeEqual(got, want)) return null; // check the length first
  const claims = JSON.parse(Buffer.from(body, "base64url").toString("utf8")) as Claims;
  return claims.exp * 1000 > now ? claims : null; // exp is in seconds
};

export class SecretInOutput extends Error {}

export const guard = (text: string, secrets: string[]): string => {
  for (const secret of secrets) {
    if (secret && text.includes(secret)) throw new SecretInOutput("refused: output contains a secret");
  }
  return text; // safe to log or return
};

